/**
 * ============================================================================
 * STATEFUL RULE ENGINE WRAPPER
 * Wraps the base rule engine to add state tracking and event triggering
 * ============================================================================
 */
export class StatefulRuleEngine {
    constructor(baseEngine: any, options?: {});
    engine: any;
    options: {
        triggerOnEveryChange: any;
        storeHistory: any;
        maxHistorySize: any;
        maxHistoryPerRule: any;
        stateExpirationMs: any;
        cleanupIntervalMs: any;
        enableDeepCopy: boolean;
        maxListeners: any;
        persistence: any;
        concurrency: any;
        errorRecovery: any;
    };
    previousStates: Map<any, any>;
    ruleStates: Map<any, any>;
    stateTimestamps: Map<any, any>;
    historyManager: GlobalHistoryManager | PerRuleHistoryManager;
    listeners: {
        triggered: never[];
        untriggered: never[];
        changed: never[];
        evaluated: never[];
    };
    cleanupTimer: NodeJS.Timeout | null;
    persistenceTimer: NodeJS.Timeout | null;
    pendingSaves: Set<any>;
    concurrencyManager: ParallelConcurrencyManager | SequentialConcurrencyManager | PerRuleConcurrencyManager;
    errorRecoveryManager: ErrorRecoveryManager;
    /**
     * Create concurrency manager based on configuration
     */
    createConcurrencyManager(): ParallelConcurrencyManager | SequentialConcurrencyManager | PerRuleConcurrencyManager;
    /**
     * Create error recovery manager based on configuration
     */
    createErrorRecoveryManager(): ErrorRecoveryManager;
    /**
     * Deep copy utility to prevent context mutation issues
     */
    deepCopy(obj: any, seen?: WeakMap<object, any>): any;
    /**
     * Evaluate rule with state tracking (async)
     * @param {string} ruleId - Rule identifier
     * @param {Object} rule - Rule definition
     * @param {Object} context - Evaluation context
     * @param {Object} options - Evaluation options
     * @returns {Promise<Object>} - Evaluation result
     */
    evaluate(ruleId: string, rule: Object, context: Object, options?: Object): Promise<Object>;
    /**
     * Internal evaluation logic (without concurrency control)
     */
    _evaluateInternal(ruleId: any, rule: any, context: any, options?: {}): any;
    /**
     * Determine if rule should trigger based on state change
     */
    shouldTrigger(previousResult: any, currentResult: any, hasChangeOperator: any, isPureChangeRule: any, options?: {}): any;
    /**
     * Detect type of state change
     */
    detectStateChange(previousResult: any, currentResult: any): "initial" | "triggered" | "untriggered" | "maintained-true" | "maintained-false";
    /**
     * Fire appropriate events
     */
    fireEvents(eventData: any, previousResult: any): void;
    /**
     * Add event listener
     */
    on(event: any, callback: any): void;
    /**
     * Remove event listener
     */
    off(event: any, callback: any): void;
    /**
     * Remove all listeners for a specific event or all events
     */
    removeAllListeners(event?: null): void;
    /**
     * Get the number of listeners for a specific event
     */
    getListenerCount(event: any): any;
    /**
     * Get all listener counts
     */
    getAllListenerCounts(): {};
    /**
     * Emit event to all listeners
     */
    emit(event: any, data: any): void;
    /**
     * Get history for a specific rule
     */
    getHistory(ruleId: any): any;
    /**
     * Get all history (across all rules)
     */
    getAllHistory(): any[];
    /**
     * Get history statistics
     */
    getHistoryStats(): {
        mode: string;
        totalRules: number;
        totalEvents: number;
        maxPerRule: number;
        perRule: {};
    } | {
        mode: string;
        totalRules: number;
        totalEvents: number;
        maxSize: number;
        perRule: any;
    };
    /**
     * Start the cleanup timer for expired states
     */
    startCleanupTimer(): void;
    /**
     * Stop the cleanup timer
     */
    stopCleanupTimer(): void;
    /**
     * Clean up expired states based on TTL
     */
    cleanupExpiredStates(): {
        removedCount: number;
        removedRules?: never;
        timestamp?: never;
    } | {
        removedCount: number;
        removedRules: any[];
        timestamp: string;
    };
    /**
     * Clear all state
     */
    clearState(ruleId?: null): void;
    /**
     * Get statistics about current state storage
     */
    getStateStats(): {
        totalRules: number;
        historySize: number;
        listenerCounts: {};
        oldestStateAge: number | null;
        memoryEstimate: {
            states: string;
            history: string;
            total: string;
        };
    };
    /**
     * Get the age of the oldest state in milliseconds
     */
    getOldestStateAge(): number | null;
    /**
     * Estimate memory usage (rough approximation)
     */
    estimateMemoryUsage(): {
        states: string;
        history: string;
        total: string;
    };
    /**
     * Get concurrency statistics (Phase 3.2)
     */
    getConcurrencyStats(): {
        mode: string;
        queueSize: number;
        activeEvaluations: number;
    } | {
        mode: string;
        queueSize: number;
        activeRules: number;
        ruleStats: {};
    };
    /**
     * Destroy the engine and cleanup resources
     */
    destroy(): Promise<void>;
    /**
     * Determine if a rule contains only change operators (no mixed logic)
     */
    isPureChangeRule(rule: any): boolean;
    /**
     * Batch evaluate multiple rules with enhanced error handling (async)
     * @returns {Promise<Object>} - Batch evaluation results
     */
    evaluateBatch(rules: any, context: any, options?: {}): Promise<Object>;
    /**
     * ============================================================================
     * PHASE 3: PERSISTENCE HOOKS
     * ============================================================================
     */
    /**
     * Validate persistence configuration
     */
    validatePersistenceConfig(): void;
    /**
     * Start the persistence timer for auto-save
     */
    startPersistenceTimer(): void;
    /**
     * Stop the persistence timer
     */
    stopPersistenceTimer(): void;
    /**
     * Flush all pending state saves
     */
    flushPendingSaves(): Promise<void>;
    /**
     * Mark a rule as having pending changes that need to be saved
     */
    markForSave(ruleId: any): void;
    /**
     * Manually save state for a specific rule
     */
    saveState(ruleId: any): Promise<void>;
    /**
     * Load state for a specific rule from persistence
     */
    loadState(ruleId: any): Promise<any>;
    /**
     * Serialize entire engine state to a plain object
     */
    serialize(): {
        states: {};
        history: any[];
        options: {
            triggerOnEveryChange: any;
            storeHistory: any;
            maxHistorySize: any;
            maxHistoryPerRule: any;
        };
        metadata: {
            serializedAt: string;
            ruleCount: number;
            historySize: number;
        };
    };
    /**
     * Hydrate engine state from a serialized object
     */
    hydrate(data: any): Promise<{
        restoredRules: number;
        restoredHistory: any;
        metadata: any;
    }>;
    /**
     * Save history entry to persistence
     */
    saveHistoryEntry(eventData: any): Promise<void>;
    /**
     * Phase 3.3: Error Recovery Helper Methods
     */
    /**
     * Register a fallback rule for a specific rule
     * @param {string} ruleId
     * @param {Object} fallbackRule
     */
    registerFallbackRule(ruleId: string, fallbackRule: Object): void;
    /**
     * Register a fallback value for a specific rule
     * @param {string} ruleId
     * @param {any} value
     */
    registerFallbackValue(ruleId: string, value: any): void;
    /**
     * Get error recovery statistics
     * @returns {Object}
     */
    getErrorRecoveryStats(): Object;
    /**
     * Get circuit breaker state for a rule
     * @param {string} ruleId
     * @returns {string}
     */
    getCircuitState(ruleId: string): string;
    /**
     * Reset circuit breaker for a rule
     * @param {string} ruleId - Optional specific rule
     */
    resetCircuit(ruleId: string): void;
    /**
     * Get error history for a rule
     * @param {string} ruleId
     * @returns {Array}
     */
    getErrorHistory(ruleId: string): any[];
    /**
     * Get error rate for a rule
     * @param {string} ruleId
     * @returns {Object|null}
     */
    getErrorRate(ruleId: string): Object | null;
}
import { GlobalHistoryManager } from './history/index.js';
import { PerRuleHistoryManager } from './history/index.js';
import { ParallelConcurrencyManager } from './concurrency/index.js';
import { SequentialConcurrencyManager } from './concurrency/index.js';
import { PerRuleConcurrencyManager } from './concurrency/index.js';
import { ErrorRecoveryManager } from './recovery/index.js';
